using System.ComponentModel.DataAnnotations;
using Microsoft.AspNetCore.Identity;

namespace HealthTrack.Models;
public class ApplicationUser : IdentityUser {
    [Required, StringLength(100)] public string FullName { get; set; } = "";
    public bool IsActive { get; set; } = true;
    public DateTime CreatedUtc { get; set; } = DateTime.UtcNow;
}
public class ClientProfile { [Key] public string UserId { get; set; } = ""; public ApplicationUser User { get; set; } = null!; [Range(50,250)] public decimal? HeightCm { get; set; } [StringLength(500)] public string? Goals { get; set; } }
public class TrainerProfile { [Key] public string UserId { get; set; } = ""; public ApplicationUser User { get; set; } = null!; [StringLength(120)] public string Specialty { get; set; } = "General fitness"; }
public class TrainerAssignment { public int Id { get; set; } public string TrainerId { get; set; } = ""; public ApplicationUser Trainer { get; set; } = null!; public string ClientId { get; set; } = ""; public ApplicationUser Client { get; set; } = null!; public DateTime AssignedUtc { get; set; } = DateTime.UtcNow; }
public class WorkoutPlan { public int Id { get; set; } [Required,StringLength(120)] public string Title { get; set; } = ""; [StringLength(1000)] public string Description { get; set; } = ""; public string TrainerId { get; set; } = ""; public ApplicationUser Trainer { get; set; } = null!; public string ClientId { get; set; } = ""; public ApplicationUser Client { get; set; } = null!; public DateTime CreatedUtc { get; set; } = DateTime.UtcNow; public List<WorkoutExercise> Exercises { get; set; } = new(); }
public class WorkoutExercise { public int Id { get; set; } public int WorkoutPlanId { get; set; } public WorkoutPlan WorkoutPlan { get; set; } = null!; [Required,StringLength(120)] public string Name { get; set; } = ""; [Range(1,30)] public int Sets { get; set; } = 1; [Range(1,200)] public int Repetitions { get; set; } = 1; [Range(0,240)] public int DurationMinutes { get; set; } }
public class WorkoutLog { public int Id { get; set; } public string ClientId { get; set; } = ""; public ApplicationUser Client { get; set; } = null!; public int WorkoutPlanId { get; set; } public WorkoutPlan WorkoutPlan { get; set; } = null!; [Required,StringLength(120)] public string CompletedExercise { get; set; } = ""; [Range(1,480)] public int DurationMinutes { get; set; } [Range(0,5000)] public int CaloriesBurned { get; set; } public DateTime LoggedUtc { get; set; } = DateTime.UtcNow; }
public class DietPlan { public int Id { get; set; } [Required,StringLength(120)] public string Title { get; set; } = ""; [Range(500,10000)] public int DailyCalorieTarget { get; set; } public string TrainerId { get; set; } = ""; public ApplicationUser Trainer { get; set; } = null!; public string ClientId { get; set; } = ""; public ApplicationUser Client { get; set; } = null!; public DateTime CreatedUtc { get; set; } = DateTime.UtcNow; public List<DietPlanMeal> Meals { get; set; } = new(); }
public class DietPlanMeal { public int Id { get; set; } public int DietPlanId { get; set; } public DietPlan DietPlan { get; set; } = null!; [Required,StringLength(100)] public string Name { get; set; } = ""; [Required,StringLength(500)] public string FoodDescription { get; set; } = ""; [Range(1,3000)] public int CalorieTarget { get; set; } [Range(0,200)] public decimal ProteinGrams { get; set; } public TimeOnly ScheduledTime { get; set; } }
public class MealLog { public int Id { get; set; } public string ClientId { get; set; } = ""; public ApplicationUser Client { get; set; } = null!; [Required,StringLength(120)] public string Food { get; set; } = ""; [Range(0,5000)] public int CaloriesConsumed { get; set; } [Range(0,500)] public decimal ProteinGrams { get; set; } public DateTime LoggedUtc { get; set; } = DateTime.UtcNow; }
public class HealthMetric { public int Id { get; set; } public string ClientId { get; set; } = ""; public ApplicationUser Client { get; set; } = null!; [Range(20,500)] public decimal WeightKg { get; set; } [Range(50,250)] public decimal HeightCm { get; set; } public decimal Bmi { get; set; } public DateTime RecordedUtc { get; set; } = DateTime.UtcNow; }
public enum AppointmentStatus { Pending, Approved, Rejected, Cancelled }
public class Appointment { public int Id { get; set; } public string ClientId { get; set; } = ""; public ApplicationUser Client { get; set; } = null!; public string TrainerId { get; set; } = ""; public ApplicationUser Trainer { get; set; } = null!; public DateTime StartsUtc { get; set; } [Range(15,180)] public int DurationMinutes { get; set; } = 60; [Required,StringLength(300)] public string Purpose { get; set; } = ""; public AppointmentStatus Status { get; set; } = AppointmentStatus.Pending; public DateTime CreatedUtc { get; set; } = DateTime.UtcNow; }
public class Notification { public int Id { get; set; } public string UserId { get; set; } = ""; public ApplicationUser User { get; set; } = null!; [Required,StringLength(300)] public string Message { get; set; } = ""; public bool IsRead { get; set; } public DateTime CreatedUtc { get; set; } = DateTime.UtcNow; }
public class TrainerFeedback { public int Id { get; set; } public string TrainerId { get; set; } = ""; public ApplicationUser Trainer { get; set; } = null!; public string ClientId { get; set; } = ""; public ApplicationUser Client { get; set; } = null!; [Required,StringLength(1000)] public string Message { get; set; } = ""; public DateTime CreatedUtc { get; set; } = DateTime.UtcNow; }
public class ActivityLog { public int Id { get; set; } public string UserId { get; set; } = ""; public ApplicationUser User { get; set; } = null!; [Required,StringLength(120)] public string Action { get; set; } = ""; public DateTime CreatedUtc { get; set; } = DateTime.UtcNow; }
public class SystemSetting { [Key,StringLength(80)] public string Key { get; set; } = ""; [Required,StringLength(250)] public string Value { get; set; } = ""; }
